<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';const route=useRoute(),feedback=computed(()=>route.path==='/feedback'),tab=ref('全部'),q=ref(''),app=useApplication(),feedbackItems=ref<any[]>([]),feedbackError=ref<string|null>(null),feedbackLoading=ref(false),feedbackDialog=ref<HTMLDialogElement>(),feedbackCategory=ref('WORDING'),feedbackComment=ref('');
async function loadFeedback(){if(!feedback.value||!app.session.current.value)return;feedbackLoading.value=true;feedbackError.value=null;try{feedbackItems.value=[...(await app.feedback.list(null,new AbortController().signal)).items];}catch(cause){feedbackError.value=cause instanceof Error?cause.message:'反馈列表暂不可用。';}finally{feedbackLoading.value=false;}}
async function submitFeedback(){try{await app.feedback.create({meetingId:'00000000-0000-4000-8000-000000000001',category:feedbackCategory.value,comment:feedbackComment.value});feedbackComment.value='';feedbackDialog.value?.close();await loadFeedback();}catch(cause){feedbackError.value=cause instanceof Error?cause.message:'反馈提交暂未完成。';}}
onMounted(loadFeedback);
</script>
<template><div class="layout"><div class="main"><header class="topbar"><RouterLink to="/meetings" class="topbar-home"><Icon name="list"/> 我的会议</RouterLink><span class="topbar-crumb">/ {{feedback?'我的语料反馈':'会议库'}}</span></header><main class="content"><div class="page-head"><div><h1 class="page-title">{{feedback?'我的语料反馈':'会议库'}}</h1><p class="page-desc">{{feedback?'仅展示本人提交的内容 · 会议内单次修改须经平台管理员审核后才会更新全局企业语料':'查找已发布会议成果，按知识库权限访问正式文档。'}}</p></div><RouterLink class="btn" to="/meetings">返回我的会议</RouterLink></div><div v-if="feedbackError" class="banner error" role="alert">{{feedbackError}}</div><div v-if="feedback" class="tabs" role="tablist" aria-label="反馈状态"><button v-for="name in ['全部','待审核','已通过','已驳回','需要补充']" :key="name" class="tab" role="tab" :class="{active:tab===name}" :aria-selected="tab===name" @click="tab=name">{{name}}</button><button class="btn sm" @click="feedbackDialog?.showModal()">提交反馈</button></div><div v-else class="filterbar"><input v-model="q" class="input" placeholder="搜索会议名称 / 纪要内容"/><select class="select" disabled><option>全部知识库</option></select><select class="select" disabled><option>全部分类</option></select></div><section class="card"><div style="overflow:auto"><table class="tbl"><thead><tr><template v-if="feedback"><th>类型</th><th>反馈内容</th><th>来源会议</th><th>状态</th></template><template v-else><th>会议名称</th><th>会议分类</th><th>参会人</th><th>会议日期</th><th>发布知识库</th><th>发布时间</th><th>操作</th></template></tr></thead><tbody v-if="feedback"><tr v-for="item in feedbackItems" :key="item.id"><td>{{item.category}}</td><td>{{item.comment}}</td><td>{{item.meetingId}}</td><td>{{item.state}}</td></tr><tr v-if="!feedbackItems.length"><td colspan="4" class="empty">{{feedbackLoading?'正在加载反馈…':'暂无反馈记录'}}</td></tr></tbody></table></div><div v-if="!feedback" class="empty"><Icon name="layers" :size="36"/><h2>暂无可读取的会议库成果</h2><p>已发布会议的真实正式文档，可从我的会议进入查看。</p></div></section><dialog ref="feedbackDialog" class="notice-dialog"><form method="dialog" @submit.prevent="submitFeedback"><h2>提交语料反馈</h2><label class="form-label">反馈类型<select v-model="feedbackCategory" class="select"><option value="WORDING">文字</option><option value="LABEL">标签</option><option value="ACTION_OWNER">行动负责人</option></select></label><label class="form-label">反馈内容<textarea v-model="feedbackComment" class="input" required rows="4"></textarea></label><div class="flex"><button class="btn" type="button" @click="feedbackDialog?.close()">取消</button><button class="btn primary" type="submit" :disabled="!feedbackComment.trim()">提交</button></div></form></dialog></main></div></div></template>
